def stringConversion(X, Y):
    # Create a table to store results of subproblems
    dp = [[False] * (len(Y) + 1) for _ in range(len(X) + 1)]

    # Both strings are empty
    dp[0][0] = True

    # Only X is empty
    for j in range(1, len(Y) + 1):
        dp[0][j] = False

    # Only Y is empty
    for i in range(1, len(X) + 1):
        if X[i - 1].islower():
            dp[i][0] = False
        else:
            dp[i][0] = True

    # Fill the dp table
    for i in range(1, len(X) + 1):
        for j in range(1, len(Y) + 1):
            if X[i - 1].isupper() and Y[j - 1] == X[i - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            elif X[i - 1].islower():
                if X[i - 1].upper() == Y[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1] or dp[i - 1][j]
                else:
                    dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = False

    return 1 if dp[len(X)][len(Y)] else 0

